function last_pair(x) {
    return is_null(tail(x))
           ? x
           : last_pair(tail(x));
}

function make_cycle(x) {
    set_tail(last_pair(x), x);
    return x;
}

function mystery(x) {
    function loop(x, y) {
        if (is_null(x)) {
            return y;
        } else {
            const temp = tail(x);
            set_tail(x, y);
            return loop(temp, x);
        }
    }
    return loop(x, null);
}

